import "./animated-icons.css";
import type { ReactNode, SVGProps } from "react";

export type AnimatedIconProps = Omit<SVGProps<SVGSVGElement>, "children"> & {
  size?: number;
};

type AnimatedIconFrameProps = AnimatedIconProps & {
  name: string;
  children: ReactNode;
};

export function dotPath(x: number, y: number) {
  return `M${x + 0.125} ${y}H${x}m.25 0a.25.25 0 1 1-.5 0a.25.25 0 0 1 .5 0`;
}

export function AnimatedIconFrame({
  name,
  size = 16,
  className,
  children,
  ...props
}: AnimatedIconFrameProps) {
  return (
    <svg
      className={className === undefined ? "animated-icon" : `animated-icon ${className}`}
      data-icon={name}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      {children}
    </svg>
  );
}

function noop() {}

/**
 * @name playIcon
 * @description Plays an animated icon's part animations from the start, for
 * state-driven feedback such as completing a task. Hover and focus play icons
 * through installIconHover without calling this.
 *
 * @example
 * const icon = button.querySelector<SVGSVGElement>('.animated-icon')
 * if (icon) playIcon(icon)
 */
export function playIcon(icon: SVGSVGElement) {
  icon.removeAttribute("data-play");
  icon.setAttribute("data-restart", "");
  // WORKAROUND: reading animations flushes styles so a hover-held animation restarts.
  icon.getAnimations({ subtree: true });
  icon.removeAttribute("data-restart");
  icon.setAttribute("data-play", "");
  const running = icon.getAnimations({ subtree: true }).map((animation) => animation.finished);
  Promise.all(running).then(() => icon.removeAttribute("data-play"), noop);
}

type DelayGroup = {
  openDelay: (now?: number) => number;
  show: (dismiss: () => void) => void;
  hide: (dismiss: () => void, now?: number) => void;
};

function createDelayGroup(coldDelay: number, warmWindow: number): DelayGroup {
  let current: (() => void) | null = null;
  let isShown = false;
  let hiddenAt = Number.NEGATIVE_INFINITY;

  return {
    openDelay(now = performance.now()) {
      return isShown || now - hiddenAt < warmWindow ? 0 : coldDelay;
    },
    show(dismiss) {
      if (current !== null && current !== dismiss) current();
      current = dismiss;
      isShown = true;
    },
    hide(dismiss, now = performance.now()) {
      if (current === dismiss && isShown) {
        isShown = false;
        hiddenAt = now;
      }
    },
  };
}

const hoverAttribute = "data-icon-hover";
const iconGroup = createDelayGroup(200, 300);
const pending = new WeakMap<Element, number>();
const dismissers = new WeakMap<Element, () => void>();

function triggerOf(node: EventTarget | null) {
  if (!(node instanceof Element)) return null;
  return node.closest("[data-icon-trigger]") ?? node.closest(".animated-icon");
}

function dismisserOf(trigger: Element) {
  const existing = dismissers.get(trigger);
  if (existing !== undefined) return existing;
  function dismiss() {
    window.clearTimeout(pending.get(trigger));
    trigger.removeAttribute(hoverAttribute);
  }
  dismissers.set(trigger, dismiss);
  return dismiss;
}

function reveal(trigger: Element) {
  iconGroup.show(dismisserOf(trigger));
  trigger.setAttribute(hoverAttribute, "");
}

function enter(trigger: Element) {
  window.clearTimeout(pending.get(trigger));
  const delay = iconGroup.openDelay();
  if (delay === 0) {
    reveal(trigger);
    return;
  }
  pending.set(
    trigger,
    window.setTimeout(() => reveal(trigger), delay),
  );
}

function leave(trigger: Element) {
  const dismiss = dismisserOf(trigger);
  iconGroup.hide(dismiss);
  dismiss();
}

function listen(root: Document) {
  const controller = new AbortController();
  const { signal } = controller;

  root.addEventListener(
    "pointerover",
    (event) => {
      const trigger = triggerOf(event.target);
      if (trigger !== null && trigger !== triggerOf(event.relatedTarget)) enter(trigger);
    },
    { signal },
  );
  root.addEventListener(
    "pointerout",
    (event) => {
      const trigger = triggerOf(event.target);
      if (trigger !== null && trigger !== triggerOf(event.relatedTarget)) leave(trigger);
    },
    { signal },
  );
  root.addEventListener(
    "focusin",
    (event) => {
      const trigger = triggerOf(event.target);
      if (trigger !== null && trigger.matches(":focus-visible")) enter(trigger);
    },
    { signal },
  );
  root.addEventListener(
    "focusout",
    (event) => {
      const trigger = triggerOf(event.target);
      if (trigger !== null) leave(trigger);
    },
    { signal },
  );

  return () => controller.abort();
}

const installs = new WeakMap<Document, { count: number; remove: () => void }>();

/**
 * @name installIconHover
 * @description Plays animated icons on hover or keyboard focus of a
 * [data-icon-trigger] ancestor, or of the icon itself. The first icon in a
 * chain waits a short delay and the next ones play immediately. Safe to call
 * from every component that renders icons: listeners are shared and removed
 * when the last caller cleans up.
 *
 * @example
 * useEffect(() => installIconHover(), [])
 */
export function installIconHover(root: Document = document) {
  const install = installs.get(root) ?? { count: 0, remove: listen(root) };
  install.count += 1;
  installs.set(root, install);
  let removed = false;

  return () => {
    if (removed) return;
    removed = true;
    install.count -= 1;
    if (install.count > 0) return;
    install.remove();
    installs.delete(root);
  };
}

.animated-icon {
  --ease-icon: cubic-bezier(0.32, 0, 0.12, 1);
  --ease-icon-swing: cubic-bezier(0.37, 0, 0.63, 1);
  --icon-duration-short: 600ms;
  --icon-duration: 750ms;
  --icon-duration-long: 1000ms;
  --icon-stagger: 70ms;

  flex: none;
  overflow: visible;

  /* WORKAROUND: naming the SVG tags keeps these selectors out of the universal bucket on full style recalcs. */
  & path,
  & g,
  & circle,
  & rect,
  & line,
  & polyline,
  & polygon,
  & ellipse {
    transform-box: view-box;
    transform-origin: 12px 12px;
  }

  & [data-stagger] > path:nth-child(2),
  & [data-stagger] > g:nth-child(2),
  & [data-stagger] > rect:nth-child(2) {
    --icon-index: 1;
  }
  & [data-stagger] > path:nth-child(3),
  & [data-stagger] > g:nth-child(3),
  & [data-stagger] > rect:nth-child(3) {
    --icon-index: 2;
  }
  & [data-stagger] > path:nth-child(4),
  & [data-stagger] > g:nth-child(4),
  & [data-stagger] > rect:nth-child(4) {
    --icon-index: 3;
  }
  & [data-stagger] > path:nth-child(5),
  & [data-stagger] > g:nth-child(5),
  & [data-stagger] > rect:nth-child(5) {
    --icon-index: 4;
  }
}

.animated-icon[data-restart] :is(path, g, circle, rect, line, polyline, polygon, ellipse) {
  animation: none !important;
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  & path,
  & g,
  & circle,
  & rect,
  & line,
  & polyline,
  & polygon,
  & ellipse {
    animation-duration: var(--icon-duration);
    animation-timing-function: var(--ease-icon-swing);
    animation-delay: calc(var(--icon-delay, 0ms) + var(--icon-index, 0) * var(--icon-stagger));
    animation-fill-mode: backwards;
  }
}

@keyframes icon-draw {
  from {
    stroke-dasharray: 1;
    stroke-dashoffset: 0.4;
  }
  to {
    stroke-dasharray: 1;
    stroke-dashoffset: 0;
  }
}

@keyframes icon-turn {
  from {
    transform: rotate(var(--icon-turn)) scale(var(--icon-scale, 1));
  }
}

@keyframes icon-pop {
  from {
    transform: rotate(var(--icon-turn, 0deg)) scale(var(--icon-scale));
  }
  62% {
    transform: rotate(calc(var(--icon-turn, 0deg) * -0.12))
      scale(calc(1 + (1 - var(--icon-scale)) * var(--icon-overshoot, 0.25)));
  }
}

@keyframes icon-nudge {
  35% {
    transform: translate(var(--icon-x, 0px), var(--icon-y, 0px));
  }
  70% {
    transform: translate(calc(var(--icon-x, 0px) * -0.2), calc(var(--icon-y, 0px) * -0.2));
  }
}

@keyframes icon-pulse {
  40% {
    transform: var(--icon-pulse);
  }
}

@keyframes icon-dash {
  40% {
    stroke-dasharray: var(--icon-dash);
  }
}

@keyframes icon-swing {
  20% {
    transform: rotate(var(--icon-swing));
  }
  45% {
    transform: rotate(calc(var(--icon-swing) * -0.65));
  }
  70% {
    transform: rotate(calc(var(--icon-swing) * 0.25));
  }
}

@keyframes icon-shake {
  20% {
    transform: translateX(-1.5px);
  }
  40% {
    transform: translateX(1.25px);
  }
  60% {
    transform: translateX(-0.75px);
  }
  80% {
    transform: translateX(0.4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .animated-icon:not([data-icon="loading"])
    :is(path, g, circle, rect, line, polyline, polygon, ellipse) {
    animation: none !important;
  }

  .animated-icon [data-part="fill"] {
    transition: none !important;
  }
}
